import sqlite3
import pandas as pd

def solve(data):
     con = sqlite3.connect(':memory:')
     try:
         pd.DataFrame({'amount':data['amounts']}).to_sql('sales', con, index=False)
         result = pd.read_sql_query('SELECT amount FROM sales WHERE amount > ? ORDER BY amount', con, params=(data['threshold'],))
         return result['amount'].tolist()
     finally:
         con.close()
